export type InitialFileEntry =
  | { type: 'file'; content: string }
  | { type: 'folder'; children: InitialFileTree };

export type InitialFileTree = Record<string, InitialFileEntry>;

export const initialFileContents: InitialFileTree = {
  '.gitignore': { type: 'file', content: '# 依存関係\nnode_modules/\nnpm-debug.log*\nyarn-debug.log*\nyarn-error.log*\n\n# ビルド出力\ndist/\nbuild/\ncache/\n\n# 環境変数\n.env\n.env.local\n.env.development.local\n.env.test.local\n.env.production.local\n\n' },
  '.pyxis': { type: 'folder', children: {
      'pyxis-instructions.md': { type: 'file', content: '回答は日本語で。' },
      'settings.json': { type: 'file', content: '{\n  "editor": {\n    "fontSize": 14,\n    "tabSize": 2,\n    "insertSpaces": true,\n    "wordWrap": false\n  },\n  "theme": {\n    "colorTheme": "dark",\n    "highlightTheme": "github-dark"\n  },\n  "search": {\n    "exclude": [\n      "**/node_modules",\n      "**/bower_components",\n      "**/*.code-search",\n      "**/dist",\n      "**/build",\n      "**/.git",\n      "**/.pyxis",\n      "**/coverage",\n      "**/.nuxt",\n      "**/cache"\n    ],\n    "useIgnoreFiles": true\n  },\n  "markdown": {\n    "singleLineBreaks": "breaks",\n    "math": {\n      "delimiter": "both"\n    }\n  },\n  "files": {\n    "exclude": [\n      "**/.git",\n      "**/cache"\n    ]\n  }\n}\n' }
    } },
  'README.md': { type: 'file', content: '# プロジェクトへようこそ\n\nこのプロジェクトはPyxisで作成されました。\n\n---\n\n## 使い方例\n\n### Node.js コード例\n\x60\x60\x60javascript\nconst fs = require(\'fs\');\nfs.writeFileSync(\'hello.txt\', \'Pyxisからこんにちは！\');\nconst content = fs.readFileSync(\'hello.txt\', \'utf8\');\nconsole.log(content);\n\x60\x60\x60\n\n### LaTeX 数式例\n$\nE = mc^2\n$\n$\nx = \\frac{-b \\pm \\sqrt{b^2-4ac}}{2a}\n$\n\n### 複数モニター・テーマ変更\n- 設定パネルから「テーマカラー」「個別色設定」を変更できます。\n\n### ファイル操作\n- ファイルツリーでドラッグ＆ドロップや右クリックで新規作成・削除・リネーム可能。\n- インポート/エクスポートでローカルファイルの追加やダウンロードもできます。\n\n### Git 操作例\n\x60\x60\x60bash\n# ファイル追加\ngit add .\n# コミット\ngit commit -m "初期コミット"\n# ブランチ作成・切替\ngit checkout -b feature/new-feature\n# マージ\ngit merge feature/new-feature\n# diff\ngit diff [branchName]\n\x60\x60\x60\n\n\n### WebPreview機能でのリアルタイムプレビュー\nPyxisでは、\x60homepage\x60 や \x60text-editor\x60 フォルダなど、Webアプリのエントリポイントとなるフォルダを長押し（または右クリック）し、「WebPreview」を選択することで、埋め込みiframe内でリアルタイムにサイトをプレビューできます。\n\n\n---\n\n## Mermaid記法のリアルタイム編集\n\x60\x60\x60mermaid\ngraph TB\n    subgraph "ブラウザ IndexedDB"\n        subgraph "pyxis-fs (lightning-fs)"\n            GitFS[Git仮想ファイルシステム]\n            GitObjects[.git/objects/]\n            GitRefs[.git/refs/]\n            GitHead[.git/HEAD]\n            GitIndex[.git/index]\n        end\n        \n        subgraph "PyxisProjects"\n            Projects[projects テーブル]\n            Files[files テーブル]\n        end\n    end\n    \n    subgraph "React メモリ状態"\n        ProjectFiles[projectFiles state]\n        Tabs[tabs state]\n        ActiveTab[activeTabId state]\n        NodeRuntimeFlag[nodeRuntimeOperationInProgress]\n    end\n    \n    subgraph "UI コンポーネント"\n        Terminal[Terminal.tsx]\n        FileTree[FileTree.tsx]\n        Editor[CodeEditor.tsx]\n        RunPanel[RunPanel.tsx]\n    end\n    \n    GitFS --> Terminal\n    Projects --> ProjectFiles\n    Files --> ProjectFiles\n    ProjectFiles --> FileTree\n    ProjectFiles --> Tabs\n    Tabs --> Editor\n    \n    Terminal --> GitFS\n    Editor --> Tabs\n    RunPanel --> GitFS\n    RunPanel --> Files\n\x60\x60\x60\n---\n\n## よく使うコマンド\n- \x60ls\x60, \x60cd\x60, \x60cat\x60, \x60touch\x60, \x60mkdir\x60, \x60rm\x60, \x60cp\x60, \x60mv\x60, \x60echo\x60, \x60clear\x60\n- 詳細は \x60/docs/unix-commands.md\x60 を参照\n\n## 便利機能\n- LaTeXプレビュー\n- 複数モニター対応\n- テーマカラー変更\n- ファイルのインポート/ダウンロード\n- Git/プロジェクトファイルのダウンロード\n- Mermaid記法のリアルタイム編集\n\n## 新機能\n\n#### AI Agent (Edit/Ask)\n- AIと対話してコードの編集や質問が可能。\n\n#### iframeを用いたHMRライクな開発環境\n- 埋め込みiframe内でリアルタイムに変更をプレビュー可能。(ファイル一覧から、WebPreviewを押してください)\n\n#### インポート機能の強化\n- zipファイル、画像、PDFなどのバッファコンテンツをインポート可能。\n- unzipコマンド対応でファイルを展開可能。\n---\n\n> Pyxisで快適な開発をお楽しみください！\n' },
  'docs': { type: 'folder', children: {
      'docs_git-commands.md': { type: 'file', content: '# Gitコマンドの使い方\n\nPyxisでは以下のGitコマンドが利用できます。\n\n- **git init**: 新しいリポジトリを初期化\n  - プロジェクトの初期化は「プロジェクト管理」ボタンから行います。\n- **git add [ファイル]**: ファイルをステージに追加\n  - \x60git add .\x60 で全ファイルを追加可能\n  - \x60git add *\x60 でカレントディレクトリのファイルを追加可能\n- **git commit -m "メッセージ"**: 変更をコミット\n  - \x60-m\x60 フラグでメッセージを指定\n- **git status**: 現在の状態を表示\n- **git log**: コミット履歴を表示\n- **git branch**: ブランチ一覧を表示\n  - \x60git branch -d [ブランチ名]\x60 でブランチ削除\n- **git checkout [ブランチ名]**: ブランチを切り替え\n  - \x60git checkout -b [新ブランチ名]\x60 で新しいブランチを作成して切り替え\n- **git merge [ブランチ名]**: ブランチをマージ\n  - \x60--no-ff\x60 オプションでFast-forwardを無効にしてマージ可能\n  - \x60--abort\x60 でマージを中止\n- **git reset --hard [コミットID]**: 指定コミットまで巻き戻し\n  - \x60git reset\x60 で全ファイルをアンステージング\n  - \x60git reset [ファイル]\x60 で特定ファイルをアンステージング\n- **git revert [コミットID]**: 指定コミットを打ち消すコミットを作成\n- **git diff**: 変更差分を表示\n  - \x60git diff\x60 でワーキングディレクトリの変更を表示\n  - \x60git diff --staged\x60 でステージされた変更を表示\n  - \x60git diff [コミット1] [コミット2]\x60 でコミット間の差分を表示\n\n詳細は画面のGitパネルやヒストリーをご参照ください。\n' },
      'getting-started.md': { type: 'file', content: '# スタートガイド\n\nこのプロジェクトの使用方法について説明します。\n\n1. コードエディタでファイルを編集\n2. ターミナルでコマンド実行\n3. Gitパネルで履歴管理\n' },
      'unix-commands.md': { type: 'file', content: '# ターミナルで使えるUnixコマンド\n\nPyxisのターミナルでは以下のコマンドが利用できます（一部制限あり）。\n\n- **ls**: ディレクトリの内容を表示\n- **cd [ディレクトリ]**: ディレクトリを移動\n  - 引数なしで実行するとプロジェクトルートに移動\n- **pwd**: 現在のパスを表示\n- **cat [ファイル]**: ファイルの内容を表示\n- **touch [ファイル]**: 空ファイルを作成\n- **mkdir [ディレクトリ]**: ディレクトリを作成\n  - \x60-p\x60 オプションで親ディレクトリも同時に作成可能\n- **rm [ファイル/ディレクトリ]**: ファイルやディレクトリを削除\n  - \x60-r\x60 または \x60-rf\x60 オプションでディレクトリを再帰的に削除\n- **cp [元] [先]**: ファイルをコピー\n- **mv [元] [先]**: ファイルを移動/リネーム\n- **echo [文字列]**: 文字列を表示\n  - \x60>\x60 を使用してファイルにリダイレクト可能\n- **clear**: 画面をクリア\n\n※ npmコマンドは現在開発中です。\n\n詳細はターミナルで**help**コマンドを実行してください。\n' }
    } },
  'src': { type: 'folder', children: {
      'code-review': { type: 'folder', children: {
          'bad.comment.ts': { type: 'file', content: 'type User = {\n  // 全部 optional / nullable になっている。\n  // こうすると、どの値が本当に省略可能なのか分からない。\n  id?: string | null;\n  name?: string | null;\n  age?: number | null;\n  email?: string | null;\n  role?: string | null;\n};\n\ntype Item = {\n  // price や count が本当に欠ける仕様なのか、\n  // API が壊れているだけなのかが型から読めない。\n  name?: string | null;\n  price?: number | null;\n  count?: number | null;\n};\n\ntype ApiResult = {\n  user?: User | null;\n  items?: Item[] | null;\n\n  // any を使った時点で、TypeScript の型安全性をかなり捨てている。\n  config?: any;\n};\n\nfunction getUserLabel(data?: any): string {\n  // any + 手動チェックの組み合わせ。\n  // JS 時代の防御コードが TypeScript に残っている状態。\n  if (!data) return "Unknown user";\n  if (!data.user) return "Unknown user";\n\n  // 変数名 u が雑。\n  // 短すぎて、読み手が一瞬止まる。\n  const u = data.user;\n\n  // User 型では id は string | null | undefined のはずなのに、\n  // typeof で再チェックしている。\n  // 型定義を信用していない。\n  const id =\n    u.id !== undefined && u.id !== null && typeof u.id === "string"\n      ? u.id\n      : "unknown-id";\n\n  // name がないときに "No Name" にしている。\n  // 画面表示用ならまだあり得るが、ドメイン上の値として扱うなら危険。\n  const name =\n    u.name !== undefined && u.name !== null && typeof u.name === "string" && u.name.length > 0\n      ? u.name\n      : "No Name";\n\n  // 年齢不明を 0 歳にしている。\n  // これはかなり危険。\n  // unknown と zero は意味が違う。\n  const age =\n    u.age !== undefined && u.age !== null && typeof u.age === "number"\n      ? u.age\n      : 0;\n\n  // 存在しないメールアドレスを仮のメールに変えている。\n  // 「メールがない」と「メールがある」を区別できなくなる。\n  const email =\n    u.email !== undefined &&\n    u.email !== null &&\n    typeof u.email === "string" &&\n    u.email.length > 0\n      ? u.email\n      : "no-email@example.com";\n\n  // ここまでで string にしているので、このチェックはほぼ意味がない。\n  if (typeof id !== "string") return "Invalid user";\n  if (typeof name !== "string") return "Invalid user";\n  if (typeof email !== "string") return "Invalid user";\n\n  // id を作っているのに使っていない。\n  // 不要な変数は、設計の迷いを残す。\n  return \x60${name} (${age}) <${email}>\x60;\n}\n\nfunction calculateTotal(data?: ApiResult | null): number {\n  return (\n    data?.items?.reduce((sum, item) => {\n      // item が存在しない可能性を毎回考えている。\n      // 本来は Item[] の配列なら item は存在する。\n      const price =\n        item &&\n        item.price !== undefined &&\n        item.price !== null &&\n        typeof item.price === "number"\n          ? item.price\n          : 0;\n\n      // count がないときに 1 とする仕様が関数内に埋まっている。\n      // これが本当に正しい業務ルールなのか分からない。\n      const count =\n        item &&\n        item.count !== undefined &&\n        item.count !== null &&\n        typeof item.count === "number"\n          ? item.count\n          : 1;\n\n      return sum + price * count;\n    }, 0) ?? 0\n  );\n}\n\nfunction getDisplayTitle(data: any): string {\n  // data, user, name のどこが壊れていても全部 "Untitled" になる。\n  // 異常と正常な欠損が区別されない。\n  if (!data) return "Untitled";\n  if (!data.user) return "Untitled";\n  if (!data.user.name) return "Untitled";\n\n  return data.user.name;\n}\n\nfunction readPort(): number {\n  // よくあるが雑な書き方。\n  // PORT=0 も 3000 になる。\n  // PORT=abc も 3000 になる。\n  // 「未指定」と「不正な指定」を区別できない。\n  const port = Number(process.env.PORT) || 3000;\n  return port;\n}\n\nfunction isAdmin(user?: User | null): boolean {\n  // role が必須なのか任意なのか分からないため、防御が増える。\n  if (!user) return false;\n  if (!user.role) return false;\n\n  // if で true/false を返すだけなら、\n  // return user.role === "admin" でよい。\n  if (user.role === "admin") {\n    return true;\n  }\n\n  return false;\n}\n\nfunction sendEmail(user?: User | null, message?: string | null): void {\n  // メールがないユーザーに仮メールを入れて送信しようとしている。\n  // 実際の送信処理なら事故になる。\n  const email =\n    user &&\n    user.email &&\n    typeof user.email === "string"\n      ? user.email\n      : "no-email@example.com";\n\n  // 空文字の message も "No message" に変わる。\n  // 空文字を許すのか、未指定だけを補うのかが曖昧。\n  const body = message || "No message";\n\n  console.log(\x60send to ${email}: ${body}\x60);\n}\n\nfunction renderUserCard(props?: any): string {\n  // props が any なので、コンポーネントの入力仕様が読めない。\n  const userName =\n    props &&\n    props.data &&\n    props.data.user &&\n    props.data.user.name &&\n    typeof props.data.user.name === "string"\n      ? props.data.user.name\n      : "Guest";\n\n  const total =\n    props &&\n    props.data &&\n    props.data.items\n      ? calculateTotal(props.data)\n      : 0;\n\n  const enabled =\n    props && props.config && props.config.enabled !== undefined\n      ? props.config.enabled\n      : true;\n\n  // render 系の関数なのに onClick を実行している。\n  // 表示と副作用が混ざっている。\n  if (props && props.onClick && typeof props.onClick === "function") {\n    props.onClick();\n  }\n\n  if (!enabled) {\n    return "disabled";\n  }\n\n  return \x60${userName}: ${total}\x60;\n}\n\nconst result = {\n  user: {\n    id: "u_001",\n    name: "Alice",\n    age: null,\n    email: null,\n    role: "admin",\n  },\n  items: [\n    { name: "Book", price: 1200, count: 2 },\n\n    // price が null。\n    // calculateTotal では 0 円扱いになるが、\n    // それが正しいのか、データ異常なのか分からない。\n    { name: "Pen", price: null, count: 3 },\n  ],\n};\n\nconsole.log(getUserLabel(result));\nconsole.log(calculateTotal(result));\nconsole.log(getDisplayTitle(result));\nconsole.log(readPort());\nconsole.log(isAdmin(result.user));\nsendEmail(result.user, "");\nconsole.log(renderUserCard({ data: result, config: {}, onClick: () => console.log("clicked") }));' },
          'bad.ts': { type: 'file', content: 'type User = {\n  id?: string | null;\n  name?: string | null;\n  age?: number | null;\n  email?: string | null;\n  role?: string | null;\n};\n\ntype Item = {\n  name?: string | null;\n  price?: number | null;\n  count?: number | null;\n};\n\ntype ApiResult = {\n  user?: User | null;\n  items?: Item[] | null;\n  config?: any;\n};\n\nfunction getUserLabel(data?: any): string {\n  if (!data) return "Unknown user";\n  if (!data.user) return "Unknown user";\n\n  const u = data.user;\n\n  const id =\n    u.id !== undefined && u.id !== null && typeof u.id === "string"\n      ? u.id\n      : "unknown-id";\n\n  const name =\n    u.name !== undefined && u.name !== null && typeof u.name === "string" && u.name.length > 0\n      ? u.name\n      : "No Name";\n\n  const age =\n    u.age !== undefined && u.age !== null && typeof u.age === "number"\n      ? u.age\n      : 0;\n\n  const email =\n    u.email !== undefined &&\n    u.email !== null &&\n    typeof u.email === "string" &&\n    u.email.length > 0\n      ? u.email\n      : "no-email@example.com";\n\n  if (typeof id !== "string") return "Invalid user";\n  if (typeof name !== "string") return "Invalid user";\n  if (typeof email !== "string") return "Invalid user";\n\n  return \x60${name} (${age}) <${email}>\x60;\n}\n\nfunction calculateTotal(data?: ApiResult | null): number {\n  return (\n    data?.items?.reduce((sum, item) => {\n      const price =\n        item &&\n        item.price !== undefined &&\n        item.price !== null &&\n        typeof item.price === "number"\n          ? item.price\n          : 0;\n\n      const count =\n        item &&\n        item.count !== undefined &&\n        item.count !== null &&\n        typeof item.count === "number"\n          ? item.count\n          : 1;\n\n      return sum + price * count;\n    }, 0) ?? 0\n  );\n}\n\nfunction getDisplayTitle(data: any): string {\n  if (!data) return "Untitled";\n  if (!data.user) return "Untitled";\n  if (!data.user.name) return "Untitled";\n\n  return data.user.name;\n}\n\nfunction readPort(): number {\n  const port = Number(process.env.PORT) || 3000;\n  return port;\n}\n\nfunction isAdmin(user?: User | null): boolean {\n  if (!user) return false;\n  if (!user.role) return false;\n\n  if (user.role === "admin") {\n    return true;\n  }\n\n  return false;\n}\n\nfunction sendEmail(user?: User | null, message?: string | null): void {\n  const email =\n    user &&\n    user.email &&\n    typeof user.email === "string"\n      ? user.email\n      : "no-email@example.com";\n\n  const body = message || "No message";\n\n  console.log(\x60send to ${email}: ${body}\x60);\n}\n\nfunction renderUserCard(props?: any): string {\n  const userName =\n    props &&\n    props.data &&\n    props.data.user &&\n    props.data.user.name &&\n    typeof props.data.user.name === "string"\n      ? props.data.user.name\n      : "Guest";\n\n  const total =\n    props &&\n    props.data &&\n    props.data.items\n      ? calculateTotal(props.data)\n      : 0;\n\n  const enabled =\n    props && props.config && props.config.enabled !== undefined\n      ? props.config.enabled\n      : true;\n\n  if (props && props.onClick && typeof props.onClick === "function") {\n    props.onClick();\n  }\n\n  if (!enabled) {\n    return "disabled";\n  }\n\n  return \x60${userName}: ${total}\x60;\n}\n\nconst result = {\n  user: {\n    id: "u_001",\n    name: "Alice",\n    age: null,\n    email: null,\n    role: "admin",\n  },\n  items: [\n    { name: "Book", price: 1200, count: 2 },\n    { name: "Pen", price: null, count: 3 },\n  ],\n};\n\nconsole.log(getUserLabel(result));\nconsole.log(calculateTotal(result));\nconsole.log(getDisplayTitle(result));\nconsole.log(readPort());\nconsole.log(isAdmin(result.user));\nsendEmail(result.user, "");\nconsole.log(renderUserCard({ data: result, config: {}, onClick: () => console.log("clicked") }));' },
          'good.ts': { type: 'file', content: 'type UserRole = "admin" | "member";\n\ntype User = {\n  id: string;\n  name: string;\n  age: number | null;\n  email: string | null;\n  role: UserRole;\n};\n\ntype Item = {\n  name: string;\n  price: number;\n  quantity: number;\n};\n\ntype AppConfig = {\n  enabled: boolean;\n};\n\ntype ApiResult = {\n  user: User;\n  items: Item[];\n  config: AppConfig;\n};\n\ntype UserCardProps = {\n  data: ApiResult;\n  onClick?: () => void;\n};\n\nfunction isObject(value: unknown): value is Record<string, unknown> {\n  return typeof value === "object" && value !== null;\n}\n\nfunction parseUserRole(value: unknown): UserRole | null {\n  if (value === "admin" || value === "member") {\n    return value;\n  }\n\n  return null;\n}\n\nfunction parseUser(value: unknown): User | null {\n  if (!isObject(value)) return null;\n\n  const role = parseUserRole(value.role);\n\n  if (\n    typeof value.id !== "string" ||\n    typeof value.name !== "string" ||\n    role === null\n  ) {\n    return null;\n  }\n\n  if (value.name.length === 0) {\n    return null;\n  }\n\n  if (value.age !== null && typeof value.age !== "number") {\n    return null;\n  }\n\n  if (value.email !== null && typeof value.email !== "string") {\n    return null;\n  }\n\n  return {\n    id: value.id,\n    name: value.name,\n    age: value.age,\n    email: value.email,\n    role,\n  };\n}\n\nfunction parseItem(value: unknown): Item | null {\n  if (!isObject(value)) return null;\n\n  if (\n    typeof value.name !== "string" ||\n    typeof value.price !== "number" ||\n    typeof value.quantity !== "number"\n  ) {\n    return null;\n  }\n\n  if (value.name.length === 0) {\n    return null;\n  }\n\n  if (value.price < 0) {\n    return null;\n  }\n\n  if (!Number.isInteger(value.quantity) || value.quantity < 1) {\n    return null;\n  }\n\n  return {\n    name: value.name,\n    price: value.price,\n    quantity: value.quantity,\n  };\n}\n\nfunction parseConfig(value: unknown): AppConfig | null {\n  if (!isObject(value)) return null;\n\n  if (typeof value.enabled !== "boolean") {\n    return null;\n  }\n\n  return {\n    enabled: value.enabled,\n  };\n}\n\nfunction parseApiResult(value: unknown): ApiResult | null {\n  if (!isObject(value)) return null;\n\n  const user = parseUser(value.user);\n  if (user === null) return null;\n\n  if (!Array.isArray(value.items)) {\n    return null;\n  }\n\n  const items = value.items.map(parseItem);\n  if (items.some((item) => item === null)) {\n    return null;\n  }\n\n  const config = parseConfig(value.config);\n  if (config === null) return null;\n\n  return {\n    user,\n    items,\n    config,\n  };\n}\n\nfunction formatUserLabel(user: User): string {\n  const ageLabel = user.age === null ? "age unknown" : String(user.age);\n  const emailLabel = user.email === null ? "email unknown" : user.email;\n\n  return \x60${user.name} (${ageLabel}) <${emailLabel}>\x60;\n}\n\nfunction calculateTotal(items: Item[]): number {\n  return items.reduce((total, item) => {\n    return total + item.price * item.quantity;\n  }, 0);\n}\n\nfunction getDisplayTitle(user: User): string {\n  return user.name;\n}\n\nfunction readPort(value: string | undefined): number {\n  if (value === undefined) {\n    return 3000;\n  }\n\n  const port = Number(value);\n\n  if (!Number.isInteger(port) || port < 0 || port > 65535) {\n    throw new Error(\x60Invalid PORT: ${value}\x60);\n  }\n\n  return port;\n}\n\nfunction isAdmin(user: User): boolean {\n  return user.role === "admin";\n}\n\nfunction createEmailMessage(user: User, message: string): string | null {\n  if (user.email === null) {\n    return null;\n  }\n\n  return \x60send to ${user.email}: ${message}\x60;\n}\n\nfunction renderUserCard(props: UserCardProps): string {\n  if (!props.data.config.enabled) {\n    return "disabled";\n  }\n\n  const userName = getDisplayTitle(props.data.user);\n  const total = calculateTotal(props.data.items);\n\n  return \x60${userName}: ${total}\x60;\n}\n\nfunction handleUserCardClick(props: UserCardProps): void {\n  props.onClick?.();\n}\n\nconst rawData: unknown = {\n  user: {\n    id: "u_001",\n    name: "Alice",\n    age: null,\n    email: null,\n    role: "admin",\n  },\n  items: [\n    { name: "Book", price: 1200, quantity: 2 },\n    { name: "Pen", price: 150, quantity: 3 },\n  ],\n  config: {\n    enabled: true,\n  },\n};\n\nconst apiResult = parseApiResult(rawData);\n\nif (apiResult === null) {\n  throw new Error("Invalid API result");\n}\n\nconst userCardProps: UserCardProps = {\n  data: apiResult,\n  onClick: () => console.log("clicked"),\n};\n\nconsole.log(formatUserLabel(apiResult.user));\nconsole.log(calculateTotal(apiResult.items));\nconsole.log(getDisplayTitle(apiResult.user));\nconsole.log(readPort(process.env.PORT));\nconsole.log(isAdmin(apiResult.user));\n\nconst emailMessage = createEmailMessage(apiResult.user, "");\nif (emailMessage !== null) {\n  console.log(emailMessage);\n}\n\nconsole.log(renderUserCard(userCardProps));\nhandleUserCardClick(userCardProps);' }
        } },
      'fibonacci.py': { type: 'file', content: '"""\nThis script provides three functionalities using NumPy:\n1. Calculate the factorial of a number.\n2. Check if a number is a prime number.\n3. Generate a Fibonacci sequence up to a given number.\n"""\n\nimport numpy as np\n\ndef factorial(n):\n    """Calculate the factorial of a number using NumPy."""\n    return np.math.factorial(n)\n\ndef is_prime(num):\n    """Check if a number is a prime number using NumPy."""\n    if num <= 1:\n        return False\n    for i in range(2, int(np.sqrt(num)) + 1):\n        if num % i == 0:\n            return False\n    return True\n\ndef fibonacci(n):\n    """Generate a Fibonacci sequence up to the nth number using NumPy."""\n    sequence = [0, 1]\n    while len(sequence) < n:\n        sequence.append(sequence[-1] + sequence[-2])\n    return sequence\n\n# Example usage\nif __name__ == "__main__":\n    # Factorial\n    num = 5\n    factorial_result = factorial(num)\n    print(f"The factorial of {num} is {factorial_result}")\n\n    # Prime check\n    prime_candidate = 29\n    prime_result = is_prime(prime_candidate)\n    print(f"Is {prime_candidate} a prime number? {\'Yes\' if prime_result else \'No\'}")\n\n    # Fibonacci sequence\n    fib_count = 10\n    fibonacci_sequence = fibonacci(fib_count)\n    print(f"The first {fib_count} numbers in the Fibonacci sequence are: {fibonacci_sequence}")\n\n    # Write output to file\n    with open("output.txt", "w") as f:\n        f.write(f"The factorial of {num} is {factorial_result}\\n")\n        f.write(f"Is {prime_candidate} a prime number? {\'Yes\' if prime_result else \'No\'}\\n")\n        f.write(f"The first {fib_count} numbers in the Fibonacci sequence are: {fibonacci_sequence}\\n")' },
      'fileOperationg.js': { type: 'file', content: 'const fs = require(\'fs\').promises;\nconst triviaList = [\n  \'カンガルーの赤ちゃんは生まれたとき2cmしかない！\',\n  \'富士山は1707年に噴火している！\',\n  \'バナナは実はベリー類に分類される！\',\n  \'日本では縦書きが一般的だけど、横書きの起源はタイプライターにあると言われてる！\'\n];\n\nasync function saveRandomTrivia() {\n  const randomTrivia = triviaList[Math.floor(Math.random() * triviaList.length)];\n  const data = { date: new Date().toISOString(), trivia: randomTrivia };\n  try {\n    await fs.writeFile(\'trivia.json\', JSON.stringify(data, null, 2), \'utf8\');\n    console.log(\'今日の豆知識を保存しました:\');\n    console.log(randomTrivia);\n  } catch (error) {\n    console.error(\'保存中にエラーが発生しました:\', error.message);\n  }\n}\n\nsaveRandomTrivia();\n' },
      'index.js': { type: 'file', content: '// メインエントリーポイント\nconsole.log("Hello, World!");\n\n// 配列処理の例\nconst arr = [1, 2, 3, 4];\nconst squared = arr.map(x => x * x);\nconsole.log("二乗した配列:", squared);\n\n// 非同期処理の例\nasync function getData() {\n  return await new Promise(res => setTimeout(() => res("3秒経ちました。"), 3000));\n}\ngetData().then(console.log);\n\nimport { add, multiply } from \'./math.js\';\n\nconsole.log(\'1 + 2 =\', add(1, 2));\nconsole.log(\'3 * 4 =\', multiply(3, 4));\n' },
      'math.js': { type: 'file', content: 'export function add(a, b) {\n  return a + b;\n}\n\nexport function multiply(a, b) {\n  return a * b;\n}\n' },
      'react': { type: 'folder', children: {
          'App.css': { type: 'file', content: '.App {\n  text-align: center;\n}\n\n.App-header {\n  background-color: #282c34;\n  min-height: 100vh;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  font-size: calc(10px + 2vmin);\n  color: white;\n}' },
          'App.jsx': { type: 'file', content: 'import React from \'react\';\nimport \'./App.css\';\n\nfunction App() {\n  return (\n    <div className="App">\n      <header className="App-header">\n        <p>\n          Hello React!\n        </p>\n      </header>\n    </div>\n  );\n}\n\nexport default App;' },
          'sample.jsx': { type: 'file', content: 'import React, { useState } from \'react\';\n\n/* ======================================\nTYPE on Terminal\n\nreact-build react/sample.jsx --tailwind\n\n======================================*/\n\n\n\n\n\n// --- Data & Assets ---\n\nconst IMAGES = {\n  hero: "https://images.unsplash.com/photo-1486325212027-8081e485255e?ixlib=rb-4.0.3&auto=format&fit=crop&w=2070&q=80",\n  about: "https://images.unsplash.com/photo-1497366216548-37526070297c?ixlib=rb-4.0.3&auto=format&fit=crop&w=2301&q=80",\n  project1: "https://images.unsplash.com/photo-1600585154340-be6161a56a0c?ixlib=rb-4.0.3&auto=format&fit=crop&w=1770&q=80",\n  project2: "https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?ixlib=rb-4.0.3&auto=format&fit=crop&w=2653&q=80",\n  project3: "https://images.unsplash.com/photo-1600566753086-00f18fb6b3ea?ixlib=rb-4.0.3&auto=format&fit=crop&w=1770&q=80",\n};\n\nconst PROJECTS = [\n  { id: 1, title: "The Glass Horizon", category: "Residential", image: IMAGES.project1 },\n  { id: 2, title: "Eco-Vertex HQ", category: "Commercial", image: IMAGES.project2 },\n  { id: 3, title: "Serenity Villa", category: "Residential", image: IMAGES.project3 },\n];\n\nconst Icons = {\n  Menu: () => (\n    <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" /></svg>\n  ),\n  X: () => (\n    <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>\n  ),\n  Leaf: () => (\n    <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M11 20c-4.5 0-8-4-8-9 0-5 5-9 9-9s9 4 9 9c0 5-3.5 9-8 9zM11 20v-9" /></svg>\n  ),\n  Building: () => (\n    <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m8-10h2M7 21h10" /></svg>\n  ),\n  Award: () => (\n    <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M12 15l-2 5l2-1l2 1l-2-5zm0-11a4 4 0 100 8 4 4 0 000-8z" /></svg>\n  ),\n  ArrowRight: () => (\n    <svg className="w-5 h-5 ml-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 8l4 4m0 0l-4 4m4-4H3" /></svg>\n  )\n};\n\nconst Navbar = () => {\n  const [isOpen, setIsOpen] = useState(false);\n\n  return (\n    <nav className="fixed w-full bg-white/90 backdrop-blur-sm z-50 border-b border-gray-100">\n      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">\n        <div className="flex justify-between h-20 items-center">\n          {/* Logo */}\n          <div className="flex-shrink-0 flex items-center">\n            <span className="text-2xl font-serif font-bold tracking-wider text-gray-900">LUMINA</span>\n          </div>\n\n          {/* Desktop Menu */}\n          <div className="hidden md:flex space-x-8 items-center">\n            <a href="#home" className="text-gray-500 hover:text-gray-900 transition-colors text-sm font-medium tracking-wide">HOME</a>\n            <a href="#about" className="text-gray-500 hover:text-gray-900 transition-colors text-sm font-medium tracking-wide">ABOUT</a>\n            <a href="#projects" className="text-gray-500 hover:text-gray-900 transition-colors text-sm font-medium tracking-wide">PROJECTS</a>\n            <a href="#contact" className="bg-gray-900 text-white px-5 py-2 rounded-sm hover:bg-gray-800 transition-colors text-sm font-medium">CONTACT</a>\n          </div>\n\n          {/* Mobile Button */}\n          <div className="md:hidden flex items-center">\n            <button onClick={() => setIsOpen(!isOpen)} className="text-gray-500 hover:text-gray-900 focus:outline-none">\n              {isOpen ? <Icons.X /> : <Icons.Menu />}\n            </button>\n          </div>\n        </div>\n      </div>\n\n      {/* Mobile Menu */}\n      {isOpen && (\n        <div className="md:hidden bg-white border-b border-gray-100 absolute w-full">\n          <div className="px-4 pt-2 pb-6 space-y-2">\n            <a href="#home" className="block px-3 py-2 text-base font-medium text-gray-700 hover:bg-gray-50">Home</a>\n            <a href="#about" className="block px-3 py-2 text-base font-medium text-gray-700 hover:bg-gray-50">About</a>\n            <a href="#projects" className="block px-3 py-2 text-base font-medium text-gray-700 hover:bg-gray-50">Projects</a>\n            <a href="#contact" className="block px-3 py-2 text-base font-medium text-gray-900 font-bold hover:bg-gray-50">Contact Us</a>\n          </div>\n        </div>\n      )}\n    </nav>\n  );\n};\n\nconst Hero = () => (\n  <div id="home" className="relative h-screen w-full overflow-hidden">\n    <div className="absolute inset-0">\n      <img src={IMAGES.hero} alt="Modern Architecture" className="w-full h-full object-cover" />\n      <div className="absolute inset-0 bg-gray-900/40"></div>\n    </div>\n    <div className="relative max-w-7xl mx-auto px-4 h-full flex items-center">\n      <div className="text-white max-w-2xl">\n        <h1 className="text-5xl md:text-7xl font-serif font-medium mb-6 leading-tight">\n          Designing the Future, <br /> Respecting the Past.\n        </h1>\n        <p className="text-lg md:text-xl text-gray-200 mb-10 font-light max-w-lg">\n          Lumina Architecture blends sustainable innovation with timeless design to create spaces that inspire.\n        </p>\n        <a href="#projects" className="inline-flex items-center border border-white text-white px-8 py-3 hover:bg-white hover:text-gray-900 transition-all duration-300 tracking-widest text-sm">\n          VIEW PORTFOLIO\n          <Icons.ArrowRight />\n        </a>\n      </div>\n    </div>\n  </div>\n);\n\nconst Services = () => (\n  <section className="py-24 bg-white">\n    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">\n      <div className="text-center mb-16">\n        <h2 className="text-3xl md:text-4xl font-serif font-medium text-gray-900 mb-4">Our Expertise</h2>\n        <div className="w-16 h-0.5 bg-gray-300 mx-auto"></div>\n      </div>\n\n      <div className="grid grid-cols-1 md:grid-cols-3 gap-12">\n        {/* Service 1 */}\n        <div className="text-center group p-6 hover:bg-gray-50 transition-colors duration-300">\n          <div className="w-16 h-16 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-6 text-gray-800 group-hover:bg-gray-200 transition-colors">\n            <Icons.Building />\n          </div>\n          <h3 className="text-xl font-medium text-gray-900 mb-3">Urban Planning</h3>\n          <p className="text-gray-500 leading-relaxed">\n            Integrating modern structures into evolving cityscapes with a focus on community and flow.\n          </p>\n        </div>\n\n        {/* Service 2 */}\n        <div className="text-center group p-6 hover:bg-gray-50 transition-colors duration-300">\n          <div className="w-16 h-16 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-6 text-gray-800 group-hover:bg-gray-200 transition-colors">\n            <Icons.Leaf />\n          </div>\n          <h3 className="text-xl font-medium text-gray-900 mb-3">Sustainable Design</h3>\n          <p className="text-gray-500 leading-relaxed">\n            Eco-conscious materials and energy-efficient systems that reduce carbon footprints.\n          </p>\n        </div>\n\n        {/* Service 3 */}\n        <div className="text-center group p-6 hover:bg-gray-50 transition-colors duration-300">\n          <div className="w-16 h-16 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-6 text-gray-800 group-hover:bg-gray-200 transition-colors">\n            <Icons.Award />\n          </div>\n          <h3 className="text-xl font-medium text-gray-900 mb-3">Interior Renovation</h3>\n          <p className="text-gray-500 leading-relaxed">\n            Transforming existing spaces into modern sanctuaries through light, space, and texture.\n          </p>\n        </div>\n      </div>\n    </div>\n  </section>\n);\n\nconst About = () => (\n  <section id="about" className="py-24 bg-gray-50">\n    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">\n      <div className="grid grid-cols-1 lg:grid-cols-2 gap-16 items-center">\n        <div className="relative h-96 lg:h-[600px]">\n          <img src={IMAGES.about} alt="Architects working" className="w-full h-full object-cover shadow-xl" />\n          <div className="absolute -bottom-6 -right-6 bg-white p-8 shadow-lg hidden md:block">\n            <p className="text-4xl font-serif font-bold text-gray-900">15+</p>\n            <p className="text-gray-500 text-sm tracking-wider uppercase mt-1">Years Experience</p>\n          </div>\n        </div>\n        <div>\n          <h2 className="text-3xl md:text-4xl font-serif font-medium text-gray-900 mb-6">\n            We build environments that shape how you live.\n          </h2>\n          <p className="text-gray-600 text-lg mb-6 leading-relaxed">\n            At Lumina, we believe architecture is more than just shelter—it\'s a dialogue between human needs and the natural environment. Founded in 2010, our firm has been at the forefront of the sustainable luxury movement.\n          </p>\n          <p className="text-gray-600 mb-8 leading-relaxed">\n            Our team of 20+ architects and designers work collaboratively to deliver projects that stand the test of time, both aesthetically and structurally.\n          </p>\n          <button className="border-b border-gray-900 text-gray-900 pb-1 hover:text-gray-600 hover:border-gray-600 transition-colors font-medium">\n            READ OUR STORY\n          </button>\n        </div>\n      </div>\n    </div>\n  </section>\n);\n\nconst Portfolio = () => (\n  <section id="projects" className="py-24 bg-white">\n    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">\n      <div className="flex justify-between items-end mb-12">\n        <div>\n          <h2 className="text-3xl md:text-4xl font-serif font-medium text-gray-900 mb-2">Selected Works</h2>\n          <p className="text-gray-500">A glimpse into our recent architectural endeavors.</p>\n        </div>\n        <a href="#" className="hidden md:flex items-center text-sm font-medium text-gray-900 hover:text-gray-600">\n          VIEW ALL <Icons.ArrowRight />\n        </a>\n      </div>\n\n      <div className="grid grid-cols-1 md:grid-cols-3 gap-8">\n        {PROJECTS.map((project) => (\n          <div key={project.id} className="group cursor-pointer">\n            <div className="relative overflow-hidden mb-4 h-80">\n              <div className="absolute inset-0 bg-black/20 group-hover:bg-black/0 transition-colors duration-500 z-10"></div>\n              <img\n                src={project.image}\n                alt={project.title}\n                className="w-full h-full object-cover transform group-hover:scale-105 transition-transform duration-700 ease-out"\n              />\n            </div>\n            <h3 className="text-xl font-medium text-gray-900 group-hover:text-gray-600 transition-colors">{project.title}</h3>\n            <p className="text-sm text-gray-500 mt-1 uppercase tracking-wider">{project.category}</p>\n          </div>\n        ))}\n      </div>\n\n      <div className="mt-12 text-center md:hidden">\n        <a href="#" className="inline-flex items-center text-sm font-medium text-gray-900 border border-gray-300 px-6 py-3">\n          VIEW ALL PROJECTS\n        </a>\n      </div>\n    </div>\n  </section>\n);\n\nconst Contact = () => (\n  <section id="contact" className="py-24 bg-gray-900 text-white">\n    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">\n      <div className="grid grid-cols-1 md:grid-cols-2 gap-16">\n        <div>\n          <h2 className="text-3xl md:text-4xl font-serif font-medium mb-6">Start your project</h2>\n          <p className="text-gray-400 mb-10 text-lg">\n            Ready to bring your vision to life? Contact our team for a consultation on your next residential or commercial project.\n          </p>\n\n          <div className="space-y-6">\n            <div>\n              <h4 className="text-sm font-bold uppercase tracking-wider text-gray-500 mb-2">Address</h4>\n              <p className="text-white">1024 Innovation Blvd, Suite 500<br />Tokyo, Japan 100-0001</p>\n            </div>\n            <div>\n              <h4 className="text-sm font-bold uppercase tracking-wider text-gray-500 mb-2">Email</h4>\n              <p className="text-white">hello@lumina-arch.com</p>\n            </div>\n            <div>\n              <h4 className="text-sm font-bold uppercase tracking-wider text-gray-500 mb-2">Phone</h4>\n              <p className="text-white">+81 (0)3 1234 5678</p>\n            </div>\n          </div>\n        </div>\n\n        <div className="bg-white/5 p-8 rounded-sm border border-white/10">\n          <form className="space-y-6" onSubmit={(e) => e.preventDefault()}>\n            <div>\n              <label className="block text-sm font-medium text-gray-300 mb-2">Name</label>\n              <input type="text" className="w-full bg-gray-800 border border-gray-700 text-white px-4 py-3 focus:outline-none focus:border-white transition-colors" placeholder="John Doe" />\n            </div>\n            <div>\n              <label className="block text-sm font-medium text-gray-300 mb-2">Email</label>\n              <input type="email" className="w-full bg-gray-800 border border-gray-700 text-white px-4 py-3 focus:outline-none focus:border-white transition-colors" placeholder="john@example.com" />\n            </div>\n            <div>\n              <label className="block text-sm font-medium text-gray-300 mb-2">Message</label>\n              <textarea rows="4" className="w-full bg-gray-800 border border-gray-700 text-white px-4 py-3 focus:outline-none focus:border-white transition-colors" placeholder="Tell us about your project..."></textarea>\n            </div>\n            <button className="w-full bg-white text-gray-900 font-bold py-4 hover:bg-gray-200 transition-colors">\n              SEND MESSAGE\n            </button>\n          </form>\n        </div>\n      </div>\n    </div>\n  </section>\n);\n\nconst Footer = () => (\n  <footer className="bg-black text-white py-12 border-t border-gray-800">\n    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 flex flex-col md:flex-row justify-between items-center">\n      <div className="mb-4 md:mb-0">\n        <span className="text-2xl font-serif font-bold tracking-wider">LUMINA</span>\n      </div>\n      <div className="flex space-x-6 text-sm text-gray-400">\n        <a href="#" className="hover:text-white transition-colors">Instagram</a>\n        <a href="#" className="hover:text-white transition-colors">LinkedIn</a>\n        <a href="#" className="hover:text-white transition-colors">Twitter</a>\n      </div>\n      <div className="mt-4 md:mt-0 text-gray-500 text-xs">\n        &copy; 2024 Lumina Architecture. All rights reserved.\n      </div>\n    </div>\n  </footer>\n);\n\n// --- Main App Component ---\n\nexport default function App() {\n  return (\n    <div className="min-h-screen bg-white font-sans text-gray-900 scroll-smooth">\n      <Navbar />\n      <main>\n        <Hero />\n        <Services />\n        <About />\n        <Portfolio />\n        <Contact />\n      </main>\n      <Footer />\n    </div>\n  );\n}\n' }
        } },
      'readline_test.js': { type: 'file', content: 'const readline = require(\'readline\');\n\n// Small helper: do not modify rl instance, offer Promise-style questions\nfunction questionAsync(rlIface, q) {\n  return new Promise((resolve) => rlIface.question(q, (ans) => resolve(ans)));\n}\n\nconsole.log(\'🚀 ReadLine モジュールテスト開始\');\n\n// 基本的なインターフェース\nconst rl = readline.createInterface({\n  input: process.stdin,\n  output: process.stdout,\n  prompt: \'REPL> \',\n  historySize: 100\n});\n\nconsole.log(\'✅ インターフェース作成完了\');\n\n// まず履歴に何かを追加するためのテスト質問\nconsole.log(\'📝 最初の質問\');\nrl.question(\'最初の質問 - 何か入力してください: \', (answer1) => {\n  console.log(\x60入力1: "${answer1}"\x60);\n  console.log(\'📋 現在の履歴:\', rl.history);\n  \n  console.log(\'📝 二番目の質問\');\n  rl.question(\'二番目の質問 - 別の何かを入力してください: \', (answer2) => {\n    console.log(\x60入力2: "${answer2}"\x60);\n    console.log(\'📋 現在の履歴:\', rl.history);\n    \n    console.log(\'🎯 カーソル制御テスト開始\');\n    \n    // カーソル制御テスト\n    console.log(\'移動前の位置\');\n    const result1 = readline.cursorTo(process.stdout, 10, 5);\n    console.log(\'カーソル移動結果:\', result1);\n    \n    const result2 = readline.clearLine(process.stdout, 0);\n    console.log(\'行クリア結果:\', result2);\n    \n    console.log(\'カーソル制御完了\');\n    \n    // 履歴クリアテスト (use rl.history directly)\n    console.log(\'🗑️ 履歴クリア前:\', rl.history);\n    rl.history = [];\n    console.log(\'🗑️ 履歴クリア後:\', rl.history);\n    \n    rl.close();\n    console.log(\'🏁 テスト完了\');\n  });\n});\n\nrl.setPrompt(\'Enter a command (type "exit" to quit): \');\nrl.prompt();\n\nrl.on(\'line\', (input) => {\n  const command = input.trim();\n  \n  if (command === \'exit\') {\n    console.log(\'Goodbye!\');\n    rl.close();\n    return;\n  }\n  \n  if (command === \'hello\') {\n    console.log(\'Hello there!\');\n  } else if (command === \'time\') {\n    console.log(\'Current time:\', new Date().toLocaleString());\n  } else if (command === \'help\') {\n    console.log(\'Available commands: hello, time, help, exit\');\n  } else if (command === \'\') {\n    // 空の入力は無視\n  } else {\n    console.log(\x60Unknown command: ${command}. Type "help" for available commands.\x60);\n  }\n  \n  rl.prompt();\n});\n\nrl.on(\'close\', () => {\n  console.log(\'Interface closed\');\n});\n\n// Promise-based question test (uses local helper)\nasync function promptTest() {\n  console.log(\'\\n=== Promise-based Question Test ===\');\n  const r = readline.createInterface({ input: process.stdin, output: process.stdout });\n  try {\n    const name = await questionAsync(r, \'Enter your name: \');\n    const age = await questionAsync(r, \'Enter your age: \');\n    const city = await questionAsync(r, \'Enter your city: \');\n\n    console.log(\'\\nProfile:\');\n    console.log(\x60Name: ${name}\x60);\n    console.log(\x60Age: ${age}\x60);\n    console.log(\x60City: ${city}\x60);\n  } catch (error) {\n    console.error(\'Error during input:\', error);\n  } finally {\n    r.close();\n  }\n}\n\n// Simple basic test\nasync function basicTest() {\n  const tmp = readline.createInterface({ input: process.stdin, output: process.stdout });\n  try {\n    const resp = await questionAsync(tmp, \'BasicTest - enter something: \');\n    console.log(\'BasicTest received:\', resp);\n  } finally {\n    tmp.close();\n  }\n}\n\n// Interactive interface test: simple loop, stop on \'exit\' or after 3 commands\nasync function interfaceTest() {\n  const tmp = readline.createInterface({ input: process.stdin, output: process.stdout, prompt: \'IT> \' });\n  console.log(\'InterfaceTest: type commands (hello/time/help/exit). Will auto-stop after 3 commands.\');\n  let count = 0;\n  return new Promise((resolve) => {\n    const onLine = (line) => {\n      const cmd = String(line).trim();\n      count++;\n      if (cmd === \'exit\' || count >= 3) {\n        tmp.removeListener(\'line\', onLine);\n        tmp.close();\n        resolve();\n        return;\n      }\n      if (cmd === \'hello\') console.log(\'Hello there!\');\n      else if (cmd === \'time\') console.log(\'Current time:\', new Date().toLocaleString());\n      else if (cmd === \'help\') console.log(\'Available commands: hello, time, help, exit\');\n      else if (cmd === \'\') {/* ignore */}\n      else console.log(\x60Unknown command: ${cmd}\x60);\n      tmp.prompt();\n    };\n\n    tmp.on(\'line\', onLine);\n    tmp.prompt();\n  });\n}\n\n// main runner\nasync function main() {\n  console.log(\'Choose a test:\');\n  console.log(\'1. Basic question test\');\n  console.log(\'2. Interactive interface test\');\n  console.log(\'3. Promise-based questions test\');\n\n  const tempRl = readline.createInterface({ input: process.stdin, output: process.stdout });\n  let choice;\n  try {\n    choice = await questionAsync(tempRl, \'Enter your choice (1-3): \');\n  } finally {\n    tempRl.close();\n  }\n\n  switch ((choice || \'\').trim()) {\n    case \'1\':\n      await basicTest();\n      break;\n    case \'2\':\n      await interfaceTest();\n      break;\n    case \'3\':\n      await promptTest();\n      break;\n    default:\n      console.log(\'Invalid choice. Running basic test...\');\n      await basicTest();\n      break;\n  }\n\n  console.log(\'\\nTest completed!\');\n}\n\n// テスト実行\nmain().catch(console.error);\n' },
      'run-test.sh': { type: 'file', content: '#!/usr/bin/env bash\nset -euo pipefail\n\nSCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"\n# Prefer repository root (parent of initial_files), but if the environment forbids\n# navigating outside the script directory (some sandboxes), fall back to script dir.\ntry_root="$(cd "$SCRIPT_DIR/.." 2>/dev/null && pwd || true)"\nif [ -n "$try_root" ] && [ "$try_root" != "$SCRIPT_DIR" ]; then\n  ROOT_DIR="$try_root"\nelse\n  ROOT_DIR="$SCRIPT_DIR"\nfi\nif ! cd "$ROOT_DIR" 2>/dev/null; then\n  echo "Warning: cannot cd to project root ($ROOT_DIR); continuing from $PWD" >&2\nfi\n\necho "== run-test.sh: Environment =="\necho "PWD: $(pwd)"\necho "---"\nfor i in {1..5}; do\n  echo "カウント: $i"\ndone\nnode src/index.js\necho "run-test.sh finished successfully"\n' },
      'typescript': { type: 'folder', children: {
          'hello.ts': { type: 'file', content: '// TypeScript基本サンプル - Hello World\n\n// 型アノテーション付き変数\nconst message: string = \'Hello, TypeScript!\';\nconst count: number = 42;\nconst isActive: boolean = true;\n\n// 関数の型定義\nfunction greet(name: string): string {\n  return \x60Hello, ${name}!\x60;\n}\n\n// インターフェース定義\ninterface User {\n  name: string;\n  age: number;\n  email?: string; // オプショナルプロパティ\n}\n\n// インターフェースを使用した関数\nfunction createUser(name: string, age: number): User {\n  return {\n    name,\n    age,\n  };\n}\n\n// ジェネリクス関数\nfunction identity<T>(value: T): T {\n  return value;\n}\n\n// 実行\nconsole.log(message);\nconsole.log(\x60Count: ${count}\x60);\nconsole.log(\x60Active: ${isActive}\x60);\n\nconsole.log(greet(\'TypeScript\'));\n\nconst user = createUser(\'Alice\', 25);\nconsole.log(\'User:\', user);\n\nconst numResult = identity<number>(100);\nconst strResult = identity<string>(\'Hello\');\nconsole.log(\'Identity results:\', numResult, strResult);\n' },
          'math.ts': { type: 'file', content: '// ES Moduleサンプル - モジュールのインポート/エクスポート\n\n// 名前付きエクスポート\nexport function add(a: number, b: number): number {\n  return a + b;\n}\n\nexport function subtract(a: number, b: number): number {\n  return a - b;\n}\n\nexport function multiply(a: number, b: number): number {\n  return a * b;\n}\n\nexport function divide(a: number, b: number): number {\n  if (b === 0) {\n    throw new Error(\'Division by zero\');\n  }\n  return a / b;\n}\n\n// 定数のエクスポート\nexport const PI = 3.14159;\nexport const E = 2.71828;\n\n// クラスのエクスポート\nexport class Calculator {\n  constructor(private value: number = 0) {}\n\n  add(n: number): this {\n    this.value += n;\n    return this;\n  }\n\n  subtract(n: number): this {\n    this.value -= n;\n    return this;\n  }\n\n  multiply(n: number): this {\n    this.value *= n;\n    return this;\n  }\n\n  divide(n: number): this {\n    if (n === 0) {\n      throw new Error(\'Division by zero\');\n    }\n    this.value /= n;\n    return this;\n  }\n\n  getValue(): number {\n    return this.value;\n  }\n\n  reset(): this {\n    this.value = 0;\n    return this;\n  }\n}\n\n// デフォルトエクスポート\nexport default class MathUtils {\n  static square(n: number): number {\n    return n * n;\n  }\n\n  static cube(n: number): number {\n    return n * n * n;\n  }\n\n  static sqrt(n: number): number {\n    if (n < 0) {\n      throw new Error(\'Cannot calculate square root of negative number\');\n    }\n    return Math.sqrt(n);\n  }\n\n  static power(base: number, exponent: number): number {\n    return Math.pow(base, exponent);\n  }\n}\n' },
          'use-math.ts': { type: 'file', content: '// ES Module使用例 - math.tsのインポート\n\n// デフォルトインポート\nimport MathUtils from \'./math\';\n\n// 名前付きインポート\nimport { add, subtract, multiply, divide, PI, Calculator } from \'./math\';\n\n// すべてインポート\nimport * as MathModule from \'./math\';\n\nconsole.log(\'=== 基本的な算術演算 ===\');\nconsole.log(\'10 + 5 =\', add(10, 5));\nconsole.log(\'10 - 5 =\', subtract(10, 5));\nconsole.log(\'10 * 5 =\', multiply(10, 5));\nconsole.log(\'10 / 5 =\', divide(10, 5));\n\nconsole.log(\'\\n=== 定数 ===\');\nconsole.log(\'PI =\', PI);\nconsole.log(\'円の面積 (r=5):\', PI * 5 * 5);\n\nconsole.log(\'\\n=== Calculatorクラス ===\');\nconst calc = new Calculator(10);\nconst result = calc\n  .add(5)\n  .multiply(2)\n  .subtract(10)\n  .getValue();\nconsole.log(\'(10 + 5) * 2 - 10 =\', result);\n\nconsole.log(\'\\n=== MathUtilsクラス ===\');\nconsole.log(\'5の2乗 =\', MathUtils.square(5));\nconsole.log(\'3の3乗 =\', MathUtils.cube(3));\nconsole.log(\'√16 =\', MathUtils.sqrt(16));\nconsole.log(\'2の10乗 =\', MathUtils.power(2, 10));\n\nconsole.log(\'\\n=== 名前空間インポート ===\');\nconsole.log(\'MathModule.add(3, 4) =\', MathModule.add(3, 4));\nconsole.log(\'MathModule.PI =\', MathModule.PI);\nconsole.log(\'MathModule.default.square(7) =\', MathModule.default.square(7));\n' }
        } }
    } },
  'web': { type: 'folder', children: {
      'index.html': { type: 'file', content: '<!doctype html>\n<html lang="ja">\n  <head>\n    <meta charset="UTF-8" />\n    <meta name="viewport" content="width=device-width, initial-scale=1.0" />\n    <title>HTML / CSS / JavaScript の基礎</title>\n    <link rel="stylesheet" href="./style.css" />\n  </head>\n  <body>\n    <header id="page-header" class="site-header">\n      <p class="eyebrow">Web Basics</p>\n      <h1>HTML / CSS / JavaScript を触ってみよう</h1>\n      <p>\n        HTMLで要素を作り、CSSで見た目を整え、JavaScriptで画面を更新します。\n      </p>\n    </header>\n\n    <main class="layout">\n      <section class="lesson-card">\n        <h2>1. HTML はページの部品を作る</h2>\n        <p>\n          この見出し、文章、入力欄、ボタンはすべてHTMLの要素です。\n          <code>id</code> は1つの要素を指定したいとき、\n          <code>class</code> は同じ種類の要素をまとめて指定したいときに使います。\n        </p>\n\n        <label class="field" for="name-input">\n          表示する名前\n          <input id="name-input" type="text" value="CodeCanvas" />\n        </label>\n\n        <button id="update-button" class="primary-button" type="button">\n          メッセージを更新\n        </button>\n      </section>\n\n      <section class="lesson-card highlight-box">\n        <h2>2. CSS は見た目を整える</h2>\n        <p>\n          この枠は <code>.lesson-card</code> と\n          <code>.highlight-box</code> というclassで装飾されています。\n          ページ上部のheaderは <code>#page-header</code> というidでも指定できます。\n        </p>\n\n        <ul class="sample-list">\n          <li>タグ名指定: <code>body</code>, <code>h1</code>, <code>button</code></li>\n          <li>class指定: <code>.lesson-card</code>, <code>.primary-button</code></li>\n          <li>id指定: <code>#message</code>, <code>#update-button</code></li>\n        </ul>\n      </section>\n\n      <section class="lesson-card">\n        <h2>3. JavaScript はHTMLの要素を更新する</h2>\n        <p id="message" class="message">\n          ここはJavaScriptで書き換えられる文章です。\n        </p>\n\n        <div class="button-row">\n          <button id="count-button" type="button">クリック数を増やす</button>\n          <button id="theme-button" type="button">色を切り替える</button>\n        </div>\n\n        <p class="counter">\n          クリック数: <span id="count">0</span>\n        </p>\n      </section>\n    </main>\n\n    <script src="./script.js"></script>\n  </body>\n</html>\n' },
      'script.js': { type: 'file', content: 'const nameInput = document.querySelector("#name-input");\nconst updateButton = document.querySelector("#update-button");\nconst message = document.querySelector("#message");\nconst countButton = document.querySelector("#count-button");\nconst themeButton = document.querySelector("#theme-button");\nconst count = document.querySelector("#count");\n\nlet clickCount = 0;\n\nupdateButton.addEventListener("click", () => {\n  const name = nameInput.value.trim() || "ゲスト";\n  message.textContent = \x60こんにちは、${name}さん。JavaScriptでHTMLの文章を更新しました。\x60;\n});\n\ncountButton.addEventListener("click", () => {\n  clickCount += 1;\n  count.textContent = clickCount;\n});\n\nthemeButton.addEventListener("click", () => {\n  document.body.classList.toggle("dark-theme");\n});\n' },
      'style.css': { type: 'file', content: 'body {\n  margin: 0;\n  font-family:\n    system-ui,\n    -apple-system,\n    BlinkMacSystemFont,\n    "Segoe UI",\n    sans-serif;\n  color: #243033;\n  background: #f6f7f2;\n}\n\n#page-header {\n  padding: 48px 24px 36px;\n  color: #ffffff;\n  background: #1f6f78;\n}\n\n.site-header h1 {\n  max-width: 760px;\n  margin: 0;\n  font-size: 36px;\n  line-height: 1.2;\n}\n\n.site-header p {\n  max-width: 760px;\n  margin: 12px 0 0;\n}\n\n.eyebrow {\n  font-size: 13px;\n  font-weight: 700;\n  letter-spacing: 0.08em;\n  text-transform: uppercase;\n}\n\n.layout {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));\n  gap: 20px;\n  max-width: 1080px;\n  margin: 28px auto;\n  padding: 0 20px;\n}\n\n.lesson-card {\n  padding: 22px;\n  border: 1px solid #d8ddd1;\n  border-radius: 8px;\n  background: #ffffff;\n}\n\n.lesson-card h2 {\n  margin-top: 0;\n  font-size: 20px;\n}\n\n.highlight-box {\n  border-color: #e0b84d;\n  background: #fff9e8;\n}\n\n.field {\n  display: grid;\n  gap: 8px;\n  margin-top: 18px;\n  font-weight: 700;\n}\n\ninput {\n  padding: 10px 12px;\n  border: 1px solid #b8c3c7;\n  border-radius: 6px;\n  font: inherit;\n}\n\nbutton {\n  padding: 10px 14px;\n  border: 1px solid #1f6f78;\n  border-radius: 6px;\n  color: #1f6f78;\n  background: #ffffff;\n  font: inherit;\n  font-weight: 700;\n  cursor: pointer;\n}\n\nbutton:hover {\n  background: #e7f4f5;\n}\n\n.primary-button {\n  margin-top: 14px;\n  color: #ffffff;\n  background: #1f6f78;\n}\n\n.primary-button:hover {\n  background: #195d64;\n}\n\n.sample-list {\n  padding-left: 20px;\n}\n\n.message {\n  padding: 14px;\n  border-left: 4px solid #1f6f78;\n  background: #eef8f9;\n  font-weight: 700;\n}\n\n.button-row {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 10px;\n}\n\n.counter {\n  font-size: 18px;\n  font-weight: 700;\n}\n\n.dark-theme {\n  color: #f4f7f8;\n  background: #1f2933;\n}\n\n.dark-theme .lesson-card {\n  color: #f4f7f8;\n  border-color: #52616b;\n  background: #2f3a44;\n}\n\n.dark-theme .highlight-box {\n  background: #3b3322;\n}\n\n.dark-theme .message {\n  color: #143034;\n}\n' }
    } }
};
